"""Vendored helpers from the pytorch practice repo.

    source: Drishtantr/pytorch  ml_utils/toolkit.py
    PR:     Drishtantr/pytorch#27
    commit: abc4bf8

The two repos share no package, so these helpers are copied rather than
imported. Upstream ``toolkit.py`` only re-exports from sibling modules; those
siblings are not vendored here, so the definitions are inlined instead. The
public surface and the import-time check mirror upstream exactly.

Do not edit this file to fix a bug -- fix it upstream and re-vendor, or the
two copies drift and the header above becomes a lie.
"""

import math
import time

__all__ = ["pass_rate", "time_call", "top_k"]

DEFAULT_REPEAT = 5


def time_call(fn, *args, repeat=DEFAULT_REPEAT, **kwargs) -> float:
    """Best-of-``repeat`` wall-clock time for ``fn(*args, **kwargs)``, in seconds."""
    if repeat < 1:
        raise ValueError(f"repeat must be >= 1, got {repeat}")

    best = math.inf
    for _ in range(repeat):
        start = time.perf_counter()
        fn(*args, **kwargs)
        best = min(best, time.perf_counter() - start)
    return best


def pass_rate(passed: int, total: int) -> float:
    """Share of cases that passed, as a percentage from 0 to 100."""
    if total <= 0:
        raise ValueError(f"total must be positive, got {total}")
    if passed < 0:
        raise ValueError(f"passed must be non-negative, got {passed}")
    if passed > total:
        raise ValueError(f"passed ({passed}) cannot exceed total ({total})")

    return 100.0 * passed / total


def top_k(scores: list[float], k: int) -> list[tuple[int, float]]:
    """The ``k`` highest scores as ``(index, score)`` pairs, best first."""
    if k <= 0:
        raise ValueError(f"k must be positive, got {k}")
    if k > len(scores):
        raise ValueError(f"k ({k}) cannot exceed len(scores) ({len(scores)})")

    ranked = sorted(enumerate(scores), key=lambda pair: pair[1], reverse=True)
    return ranked[:k]


# Mirrors upstream: catch a broken re-export at import rather than first call.
_missing = [name for name in __all__ if name not in globals()]
if _missing:
    raise ImportError(f"vendored toolkit is incomplete, missing: {_missing}")
